//! Data-driven status-effect presentation data.
//!
//! Every presentation fact of a status effect is defined by **one** data file:
//!
//! `archive/data/client/status_effects.ron` (shipped inside the client archive,
//! loaded through [`GameFileLoader`] so a server can override it without
//! rebuilding the client). The same file is embedded with `include_str!` as the
//! compiled fallback, so the archive override and the compiled table can never
//! drift apart.
//!
//! The file is generated by `tools/gen_status_effects.py` from the extracted
//! facts (`tools/status_facts.json`, `tools/extract_status_facts.py`), which
//! merge the rAthena server sources (`src/map/status.hpp` `efst_type`/`sc_type`
//! ids, `db/pre-re/status.yml` names/`Icon`/`Flags`/`CalcFlags`), the official
//! 2019 client Lua tables (`stateiconinfo.lub` English titles + buff/debuff/
//! toggle title colours, `stateiconimginfo.lub` icon names, `efstids.lub`), the
//! reverse-engineered roBrowserLegacy classic status icon/title table and the
//! curated overlay (`tools/status_effect_custom.ron`: the Assumptio aura moved
//! out of Rust, documented procedural buff glows, the extra English names, the
//! deliberate icon choices and the `SendVal*` value-label semantics).
//!
//! # Model
//!
//! One [`StatusEffectInfo`] per `EFST_*` id (sorted, unique), with:
//!
//! * `name` - English buff-bar name/tooltip title (optional: statuses whose
//!   client title is a placeholder/description keep the generic fallback name
//!   of [`crate::state::status_effects`]),
//! * `icon` - file name inside `data\texture\effect\` (the transparent status
//!   icons, not the opaque skill icons of the hotbar),
//! * `category` - `Buff`/`Debuff`/`Toggle`/`System` from the official client
//!   title colour (or the `Debuff` flag of the status database),
//! * `refresh`/`stack` - the buff-bar update policy for this status,
//! * `value_labels` - how the `value1..value3` of the status packet are
//!   formatted in the tooltip (`SendVal*` statuses only),
//! * `aura` - the persistent world glow spec, if the status has one.
//!
//! # Lookup cost
//!
//! The loaded table is a process-wide static with leaked, process-lifetime
//! strings. Lookups are a binary search over the sorted ids and allocation
//! free; the buff bar already caches the per-frame formatted tooltip strings.
//!
//! # Fallback
//!
//! A status id that is not in the table is **never** an error and never empty:
//! [`lookup`] returns `None` and the caller keeps its documented fallback
//! (generic `Status effect` name, no icon, no aura, raw value line). A
//! malformed archive override is rejected with a log line and the compiled
//! fallback is used, so a bad data file can never leave the client without
//! status presentation.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use korangar_loaders::FileLoader;
use serde::Deserialize;

use crate::graphics::Color;
use crate::loaders::GameFileLoader;

/// Data file path inside the client archive (`data\client\...`).
const DATA_PATH: &str = "data\\client\\status_effects.ron";
/// Fallback copy of the same file, compiled into the client.
const FALLBACK: &str = include_str!("../../../archive/data/client/status_effects.ron");

// ---------------------------------------------------------------------------
// Runtime model.
// ---------------------------------------------------------------------------

/// Broad buff-bar group of a status effect.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Deserialize)]
pub enum StatusEffectCategory {
    /// Positive status effect.
    Buff,
    /// Negative status effect.
    Debuff,
    /// Toggleable status effect with a persistent icon.
    Toggle,
    /// System/client status (no gameplay buff).
    System,
}

/// What re-applying an already active status does to the buff-bar entry.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default, Deserialize)]
pub enum StatusRefreshPolicy {
    /// Reset the entry and its timer (the official client behaviour).
    #[default]
    Replace,
    /// Keep the already running timer and only update name/icon/values.
    Keep,
}

/// How multiple simultaneous copies of one status are represented.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Deserialize)]
#[allow(dead_code)]
pub(crate) enum StatusStackPolicy {
    /// One buff-bar entry per (entity, status); a refresh updates it in place.
    ///
    /// The 2019 packets do not carry stack counts, so this is the only policy
    /// the buff bar can render today; the data field is explicit so a future
    /// stacking renderer can distinguish the statuses that support it.
    Single,
}

/// How one server-side status value is rendered in the buff tooltip.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Deserialize)]
pub(crate) enum StatusValueFormat {
    /// Element id; the name is resolved from the data file's element table.
    Element,
    /// Percentage (`<label>: <value>%`).
    Percent,
    /// Plain number (`<label>: <value>`).
    Number,
    /// Id (`<label>: #<value>`).
    Id,
}

/// One labelled server value of a status effect.
#[derive(Debug, Clone, Copy)]
pub(crate) struct StatusValueLabel {
    /// `value1..value3` of the status packet (`1..=3`).
    pub slot: u8,
    /// English label shown before the value.
    pub label: &'static str,
    /// Formatting of the value.
    pub format: StatusValueFormat,
}

/// Renderer of a persistent status aura.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Deserialize)]
pub enum StatusAuraKind {
    /// Ground light pool + rotating ring + camera-facing animated body shield.
    PersistentGlow,
}

/// One persistent status glow style (data-driven).
///
/// All sizes are in world units (one map cell is 10 world units) and are
/// multiplied by the entity scale, so a status glow follows a scaled monster as
/// well. The colours are sRGB tints that the textures are multiplied with.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct StatusAuraSpec {
    /// Which renderer draws the spec.
    pub kind: StatusAuraKind,
    /// Soft radial glow drawn flat on the ground below the entity.
    pub ground_texture: &'static str,
    /// Rotating ring/energy texture drawn flat on the ground.
    pub ring_texture: &'static str,
    /// Camera facing animated shield frames, played in order (looping).
    pub body_frames: &'static [&'static str],
    /// Soft camera facing light drawn around the body.
    pub body_glow_texture: &'static str,
    /// Tint of the ground layers.
    pub ground_color: Color,
    /// Tint of the animated body shield.
    pub body_color: Color,
    /// Tint of the soft camera facing body light.
    pub glow_color: Color,
    /// Radius of the ground glow in world units.
    pub ground_radius: f32,
    /// Radius of the ground ring in world units.
    pub ring_radius: f32,
    /// Rotation speed of the ground ring in radians per second.
    pub ring_rotation_speed: f32,
    /// Size (diameter) of the camera facing body shield in world units.
    pub body_size: f32,
    /// Size (diameter) of the camera facing body light in world units.
    pub body_glow_size: f32,
    /// Base alpha of the ground glow (before the pulse).
    pub ground_alpha: f32,
    /// Base alpha of the ground ring (before the pulse).
    pub ring_alpha: f32,
    /// Base alpha of the body shield (before the pulse).
    pub body_alpha: f32,
    /// Base alpha of the body light (before the pulse).
    pub body_glow_alpha: f32,
    /// Playback rate of the animated body shield in frames per second.
    pub body_frame_rate: f32,
    /// Rotation speed of the body shield in radians per second.
    pub body_rotation_speed: f32,
    /// Distance (world units) the camera facing body layers are moved towards
    /// the camera, so they are drawn in front of the entity sprite instead of
    /// being occluded by its depth.
    pub body_camera_offset: f32,
    /// Pulse speed in radians per second; the layers pulse out of phase.
    pub pulse_speed: f32,
    /// Pulse amplitude as a fraction of the base alpha (`0.25` = ±25 %).
    pub pulse_amount: f32,
    /// Height of the camera facing body layers above the entity's feet in
    /// world units (scaled, lowered while sitting by the renderer).
    pub body_height: f32,
}

/// Static presentation info of one known status effect.
#[derive(Debug, Clone, Copy)]
pub(crate) struct StatusEffectInfo {
    /// `EFST_*` id the map server sends.
    #[allow(dead_code)]
    pub id: u16,
    /// English buff-bar name; `None` keeps the caller's fallback name.
    pub name: Option<&'static str>,
    /// Status icon file name inside `data\texture\effect\`.
    pub icon: Option<&'static str>,
    /// Buff/debuff/toggle/system group.
    ///
    /// Read through [`status_effect_category`] (crate API); the buff bar keeps
    /// the icons ungrouped for now, the field is the data hook for the planned
    /// category grouping.
    #[allow(dead_code)]
    pub category: StatusEffectCategory,
    /// Re-application policy of the buff-bar entry.
    pub refresh: StatusRefreshPolicy,
    /// Stacking policy of the buff-bar entry (the 2019 packets carry no stack
    /// counts; the field is data so a future stacking renderer can use it).
    #[allow(dead_code)]
    pub stack: StatusStackPolicy,
    /// Labelled server values, empty for statuses that send no values.
    pub value_labels: &'static [StatusValueLabel],
    /// Persistent world glow, if the status has one.
    pub aura: Option<&'static StatusAuraSpec>,
}

/// The whole loaded table.
struct StatusTable {
    statuses: Vec<StatusEffectInfo>,
    element_names: Vec<&'static str>,
}

// ---------------------------------------------------------------------------
// Data file schema.
// ---------------------------------------------------------------------------

/// Accepts both a bare value and the explicit `Some(value)`/`None` RON option
/// spelling for optional row fields.
///
/// The data file is generated; writing `name: "Blessing"` (or omitting `aura`)
/// is much more readable than wrapping every optional field in `Some(...)`. The
/// untagged helper buffers the value and retries it as an [`Option`], so both
/// spellings work and typos still fail.
#[derive(Deserialize)]
#[serde(untagged)]
enum BareOrOption<T> {
    Bare(T),
    Optional(Option<T>),
}

fn deserialize_option<'de, D, T>(deserializer: D) -> Result<Option<T>, D::Error>
where
    D: serde::Deserializer<'de>,
    T: Deserialize<'de>,
{
    Ok(match BareOrOption::<T>::deserialize(deserializer)? {
        BareOrOption::Bare(value) => Some(value),
        BareOrOption::Optional(value) => value,
    })
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct StatusEffectFile {
    #[allow(dead_code)]
    provenance: String,
    #[allow(dead_code)]
    version: u32,
    value_enums: ValueEnumsFile,
    statuses: Vec<StatusRowFile>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct ValueEnumsFile {
    element: Vec<String>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct StatusRowFile {
    id: u16,
    #[serde(default, deserialize_with = "deserialize_option")]
    name: Option<String>,
    #[serde(default, deserialize_with = "deserialize_option")]
    icon: Option<String>,
    category: StatusEffectCategory,
    refresh: StatusRefreshPolicy,
    stack: StatusStackPolicy,
    #[serde(default)]
    value_labels: Vec<ValueLabelFile>,
    #[serde(default, deserialize_with = "deserialize_option")]
    aura: Option<AuraFile>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct ValueLabelFile {
    slot: u8,
    label: String,
    format: StatusValueFormat,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct AuraFile {
    kind: StatusAuraKind,
    textures: AuraTexturesFile,
    tint: AuraTintFile,
    radii: AuraRadiiFile,
    timing: AuraTimingFile,
    alpha: AuraAlphaFile,
    height: f32,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct AuraTexturesFile {
    ground: String,
    ring: String,
    body_frames: Vec<String>,
    body_glow: String,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct AuraTintFile {
    ground: (f32, f32, f32),
    body: (f32, f32, f32),
    glow: (f32, f32, f32),
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct AuraRadiiFile {
    ground: f32,
    ring: f32,
    body: f32,
    body_glow: f32,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct AuraTimingFile {
    body_frame_rate: f32,
    ring_rotation_speed: f32,
    body_rotation_speed: f32,
    body_camera_offset: f32,
    pulse_speed: f32,
    pulse_amount: f32,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct AuraAlphaFile {
    ground: f32,
    ring: f32,
    body: f32,
    body_glow: f32,
}

// ---------------------------------------------------------------------------
// Static tables.
// ---------------------------------------------------------------------------

/// The compiled fallback, parsed on first use (also used by tests and the
/// `--check-status-effects` CLI).
static COMPILED: OnceLock<StatusTable> = OnceLock::new();
/// The table loaded from the client archive, if the file exists there.
static ARCHIVE: OnceLock<StatusTable> = OnceLock::new();

fn compiled() -> &'static StatusTable {
    COMPILED.get_or_init(|| match parse(FALLBACK) {
        Ok(table) => table,
        Err(error) => {
            crate::logging::log_warn!("status effects: compiled fallback is invalid ({error})");
            StatusTable {
                statuses: Vec::new(),
                element_names: Vec::new(),
            }
        }
    })
}

fn table() -> &'static StatusTable {
    ARCHIVE.get().unwrap_or_else(compiled)
}

/// Loads the status-effect table from the client archive (or the compiled
/// fallback).
///
/// Returns the number of status entries. A malformed data file is reported and
/// the compiled fallback is used instead, so a bad override can never leave the
/// client without status presentation.
pub(crate) fn load(game_file_loader: &GameFileLoader) -> usize {
    let from_archive = game_file_loader
        .get(DATA_PATH)
        .ok()
        .map(|bytes| String::from_utf8_lossy(&bytes).into_owned());

    let Some(content) = from_archive.as_deref() else {
        let count = compiled().statuses.len();
        crate::logging::log_debug!("status effects: loaded {count} statuses from the compiled fallback");
        return count;
    };

    let loaded = match parse(content) {
        Ok(table) => {
            let count = table.statuses.len();
            crate::logging::log_debug!("status effects: loaded {count} statuses from the archive");
            table
        }
        Err(error) => {
            crate::logging::log_warn!("status effects: invalid {DATA_PATH} ({error}), using the compiled fallback");
            compiled().clone()
        }
    };

    let count = loaded.statuses.len();
    let _ = ARCHIVE.set(loaded);
    count
}

impl Clone for StatusTable {
    fn clone(&self) -> Self {
        Self {
            statuses: self.statuses.clone(),
            element_names: self.element_names.clone(),
        }
    }
}

/// The data row of a status id, or `None` if the id is unknown.
pub(crate) fn status_effect_info(status_index: u16) -> Option<&'static StatusEffectInfo> {
    lookup(status_index)
}

/// The data row of a status id, or `None` if the id is unknown.
pub(crate) fn lookup(status_index: u16) -> Option<&'static StatusEffectInfo> {
    let table = table();
    table
        .statuses
        .binary_search_by_key(&status_index, |status| status.id)
        .ok()
        .map(|index| &table.statuses[index])
}

/// The persistent glow spec of a status id, if it has one.
pub(crate) fn status_aura_spec(status_index: u16) -> Option<&'static StatusAuraSpec> {
    lookup(status_index).and_then(|status| status.aura)
}

/// The refresh policy of a status id (`Replace` for unknown ids).
pub(crate) fn refresh_policy(status_index: u16) -> StatusRefreshPolicy {
    lookup(status_index).map(|status| status.refresh).unwrap_or_default()
}

/// The element name of an rAthena element id, if the data file defines it.
fn element_name(element: usize) -> Option<&'static str> {
    table().element_names.get(element).copied()
}

/// Formats the server-side values of a status effect for the buff tooltip.
///
/// Most status effects do not send values (`value1..value3` are zero). The few
/// statuses that use them have a `value_labels` row in the data file (the
/// `SendVal*` statuses of the status database); for every other status the
/// non-zero values are shown as a generic line, so the data is never silently
/// dropped.
pub(crate) fn value_lines(status_index: u16, values: [i32; 3]) -> Vec<String> {
    if values.iter().all(|value| *value == 0) {
        return Vec::new();
    }

    let Some(status) = lookup(status_index) else {
        return vec![generic_values(values)];
    };

    if status.value_labels.is_empty() {
        return vec![generic_values(values)];
    }

    let mut lines = Vec::with_capacity(status.value_labels.len());
    for label in status.value_labels {
        let value = values[usize::from(label.slot.saturating_sub(1)).min(2)];
        let line = match label.format {
            StatusValueFormat::Element => {
                let element = usize::try_from(value).ok().and_then(element_name).unwrap_or("Unknown");
                format!("{}: {element}", label.label)
            }
            StatusValueFormat::Percent => format!("{}: {value}%", label.label),
            StatusValueFormat::Number => format!("{}: {value}", label.label),
            StatusValueFormat::Id => format!("{}: #{value}", label.label),
        };
        lines.push(line);
    }
    lines
}

/// The generic value line for statuses without value semantics.
fn generic_values(values: [i32; 3]) -> String {
    let values = values
        .iter()
        .filter(|value| **value != 0)
        .map(i32::to_string)
        .collect::<Vec<_>>()
        .join(" / ");
    format!("Value: {values}")
}

// ---------------------------------------------------------------------------
// Parsing and validation.
// ---------------------------------------------------------------------------

/// Validates a document against the schema and returns the number of statuses.
///
/// This is the `--check`-able entry point: the client binary exposes it as
/// `korangar --check-status-effects [PATH]` so CI can validate the committed
/// data file (or an archive override) without starting a window or a network
/// connection.
pub(crate) fn validate(content: &str) -> Result<usize, String> {
    parse(content).map(|table| table.statuses.len())
}

/// Validates the compiled fallback (used by `--check-status-effects` without a
/// path and by the tests).
pub(crate) fn validate_compiled() -> Result<usize, String> {
    validate(FALLBACK)
}

fn parse(content: &str) -> Result<StatusTable, String> {
    let file: StatusEffectFile = ron::from_str(content).map_err(|error| format!("schema error: {error}"))?;
    build(file)
}

fn build(file: StatusEffectFile) -> Result<StatusTable, String> {
    if file.statuses.is_empty() {
        return Err("the data file contains no status effects".to_owned());
    }
    if file.value_enums.element.is_empty() {
        return Err("the data file contains no element names".to_owned());
    }

    let element_names = file
        .value_enums
        .element
        .into_iter()
        .map(|name| {
            if name.is_empty() {
                return Err("the data file contains an empty element name".to_owned());
            }
            Ok(leak(name))
        })
        .collect::<Result<Vec<&'static str>, String>>()?;

    // One entry per status id; several rows with the same id are a data bug,
    // not a merge case.
    let mut grouped: BTreeMap<u16, StatusEffectInfo> = BTreeMap::new();
    for row in file.statuses {
        let status_id = row.id;
        if grouped.contains_key(&status_id) {
            return Err(format!("status {status_id}: duplicate id"));
        }
        let info = build_row(row)?;
        grouped.insert(status_id, info);
    }

    Ok(StatusTable {
        statuses: grouped.into_values().collect(),
        element_names,
    })
}

fn build_row(row: StatusRowFile) -> Result<StatusEffectInfo, String> {
    let status_id = row.id;

    let name = match row.name {
        Some(name) => {
            let name = name.trim().to_owned();
            if name.is_empty() || !name.is_ascii() || name.contains('#') || !name.chars().any(|character| character.is_ascii_alphabetic()) {
                return Err(format!("status {status_id}: unusable name {name:?}"));
            }
            Some(leak(name))
        }
        None => None,
    };

    let icon = match row.icon {
        Some(icon) => {
            if icon.is_empty() || !icon.to_ascii_lowercase().ends_with(".tga") {
                return Err(format!("status {status_id}: status icons must be .tga files, got {icon:?}"));
            }
            Some(leak(icon))
        }
        None => None,
    };

    let mut slots = [false; 3];
    let mut value_labels = Vec::with_capacity(row.value_labels.len());
    for label in row.value_labels {
        if !(1..=3).contains(&label.slot) {
            return Err(format!("status {status_id}: value slot {} is outside 1..3", label.slot));
        }
        let slot_index = usize::from(label.slot - 1);
        if slots[slot_index] {
            return Err(format!("status {status_id}: duplicate value slot {}", label.slot));
        }
        slots[slot_index] = true;
        if label.label.is_empty() || !label.label.is_ascii() {
            return Err(format!("status {status_id}: unusable value label {:?}", label.label));
        }
        value_labels.push(StatusValueLabel {
            slot: label.slot,
            label: leak(label.label),
            format: label.format,
        });
    }
    value_labels.sort_by_key(|label| label.slot);
    let value_labels: &'static [StatusValueLabel] = leak_slice(value_labels);

    let aura = match row.aura {
        Some(aura) => Some(build_aura(status_id, aura)?),
        None => None,
    };

    Ok(StatusEffectInfo {
        id: status_id,
        name,
        icon,
        category: row.category,
        refresh: row.refresh,
        stack: row.stack,
        value_labels,
        aura,
    })
}

fn build_aura(status_id: u16, aura: AuraFile) -> Result<&'static StatusAuraSpec, String> {
    fn texture(status_id: u16, field: &str, value: String) -> Result<&'static str, String> {
        let lower = value.to_ascii_lowercase();
        if value.is_empty() || !(lower.ends_with(".tga") || lower.ends_with(".bmp")) {
            return Err(format!(
                "status {status_id}: aura {field} is not a .tga/.bmp texture: {value:?}"
            ));
        }
        Ok(leak(value))
    }

    fn finite(status_id: u16, field: &str, value: f32) -> Result<f32, String> {
        if !value.is_finite() {
            return Err(format!("status {status_id}: aura {field} is not finite"));
        }
        Ok(value)
    }

    fn range(status_id: u16, field: &str, value: f32, low: f32, high: f32) -> Result<f32, String> {
        if !value.is_finite() || value < low || value > high {
            return Err(format!("status {status_id}: aura {field} {value} is outside {low}..={high}"));
        }
        Ok(value)
    }

    fn colour(status_id: u16, field: &str, value: (f32, f32, f32)) -> Result<Color, String> {
        for component in [value.0, value.1, value.2] {
            range(status_id, field, component, 0.0, 1.0)?;
        }
        Ok(Color::rgb(value.0, value.1, value.2))
    }

    if aura.kind != StatusAuraKind::PersistentGlow {
        return Err(format!("status {status_id}: unsupported aura kind {:?}", aura.kind));
    }
    if aura.textures.body_frames.is_empty() {
        return Err(format!("status {status_id}: aura has no body frames"));
    }

    let ground_texture = texture(status_id, "textures.ground", aura.textures.ground)?;
    let ring_texture = texture(status_id, "textures.ring", aura.textures.ring)?;
    let body_glow_texture = texture(status_id, "textures.body_glow", aura.textures.body_glow)?;
    let body_frames = aura
        .textures
        .body_frames
        .into_iter()
        .map(|frame| texture(status_id, "textures.body_frames", frame))
        .collect::<Result<Vec<&'static str>, String>>()?;
    let body_frames: &'static [&'static str] = leak_slice(body_frames);

    let ground_radius = range(status_id, "radii.ground", aura.radii.ground, 0.01, 100.0)?;
    let ring_radius = range(status_id, "radii.ring", aura.radii.ring, 0.01, 100.0)?;
    let body_size = range(status_id, "radii.body", aura.radii.body, 0.01, 100.0)?;
    let body_glow_size = range(status_id, "radii.body_glow", aura.radii.body_glow, 0.01, 100.0)?;
    let height = range(status_id, "height", aura.height, 0.01, 100.0)?;

    let timing = &aura.timing;
    Ok(leak_box(StatusAuraSpec {
        kind: aura.kind,
        ground_texture,
        ring_texture,
        body_frames,
        body_glow_texture,
        ground_color: colour(status_id, "tint.ground", aura.tint.ground)?,
        body_color: colour(status_id, "tint.body", aura.tint.body)?,
        glow_color: colour(status_id, "tint.glow", aura.tint.glow)?,
        ground_radius,
        ring_radius,
        ring_rotation_speed: finite(status_id, "timing.ring_rotation_speed", timing.ring_rotation_speed)?,
        body_size,
        body_glow_size,
        ground_alpha: range(status_id, "alpha.ground", aura.alpha.ground, 0.0, 1.0)?,
        ring_alpha: range(status_id, "alpha.ring", aura.alpha.ring, 0.0, 1.0)?,
        body_alpha: range(status_id, "alpha.body", aura.alpha.body, 0.0, 1.0)?,
        body_glow_alpha: range(status_id, "alpha.body_glow", aura.alpha.body_glow, 0.0, 1.0)?,
        body_frame_rate: range(status_id, "timing.body_frame_rate", timing.body_frame_rate, 0.0, 100.0)?,
        body_rotation_speed: finite(status_id, "timing.body_rotation_speed", timing.body_rotation_speed)?,
        body_camera_offset: range(status_id, "timing.body_camera_offset", timing.body_camera_offset, 0.0, 100.0)?,
        pulse_speed: finite(status_id, "timing.pulse_speed", timing.pulse_speed)?,
        pulse_amount: range(status_id, "timing.pulse_amount", timing.pulse_amount, 0.0, 1.0)?,
        body_height: height,
    }))
}

/// Leaks the parsed data into process lifetime storage, matching the
/// `include_str!` fallback and the renderer's `&'static` specs.
fn leak(value: String) -> &'static str {
    Box::leak(value.into_boxed_str())
}

fn leak_slice<T>(values: Vec<T>) -> &'static [T] {
    Box::leak(values.into_boxed_slice())
}

fn leak_box<T>(value: T) -> &'static T {
    Box::leak(Box::new(value))
}

#[cfg(test)]
mod tests {
    use super::{
        FALLBACK, StatusAuraKind, StatusEffectCategory, StatusRefreshPolicy, StatusStackPolicy, StatusValueFormat, lookup,
        status_aura_spec, validate, validate_compiled, value_lines,
    };

    /// Frozen snapshot of the hand-generated name/icon tables this data file
    /// replaced (kept as the transition parity oracle; see the file itself).
    const LEGACY_TABLES: &str = include_str!("../../../../tools/status_effect_legacy_tables.ron");

    #[derive(serde::Deserialize, Debug)]
    #[allow(dead_code)]
    struct LegacyTables {
        provenance: String,
        names: Vec<(u16, String)>,
        icons: Vec<(u16, String)>,
        extra_names: Vec<(u16, String)>,
    }

    fn legacy_tables() -> LegacyTables {
        // `provenance` is a documentation string; keep the parser strict about
        // the shape but tolerant about its content.
        ron::from_str(LEGACY_TABLES).expect("the legacy parity snapshot must be valid RON")
    }

    /// Old name ids whose name shifted by one because the old generator's
    /// server-enum parser skipped the `XXX_EFST_WORLDSTORE_ACTIVE` enum entry
    /// (the client/server ids themselves agree, see the facts provenance).
    const LEGACY_NAME_SHIFT: std::ops::RangeInclusive<u16> = 1064..=1072;

    #[test]
    fn compiled_fallback_is_valid() {
        let count = validate_compiled().expect("compiled status data must be valid");
        assert_eq!(count, super::table().statuses.len());
        assert!(count > 500, "the status data unexpectedly shrank to {count} entries");
        assert_eq!(validate(FALLBACK).expect("fallback must be valid"), count);
    }

    #[test]
    fn status_ids_are_sorted_and_unique() {
        let table = super::table();
        for window in table.statuses.windows(2) {
            assert!(
                window[0].id < window[1].id,
                "status table is not strictly sorted: {} then {}",
                window[0].id,
                window[1].id
            );
        }
    }

    #[test]
    fn legacy_names_are_covered() {
        let legacy = legacy_tables();
        assert_eq!(legacy.names.len(), 509);
        for (legacy_id, legacy_name) in &legacy.names {
            // The old generator's server-enum parser skipped one enum entry, so
            // its names are off by one in the drifted region; the new table uses
            // the real server ids (the client efstids.lub agrees with them).
            let expected_id = if LEGACY_NAME_SHIFT.contains(legacy_id) {
                legacy_id + 1
            } else {
                *legacy_id
            };
            let info = lookup(expected_id).unwrap_or_else(|| panic!("status {expected_id} (legacy {legacy_id}) is missing"));
            assert_eq!(
                info.name,
                Some(legacy_name.as_str()),
                "status {expected_id} (legacy {legacy_id}) name changed"
            );
        }

        // The shifted ids now carry the *correct* client title instead of the
        // old off-by-one label.
        assert_eq!(lookup(1065).unwrap().name, Some("Infinity Drink"));
        assert_eq!(lookup(1073).unwrap().name, Some("Curse of The Evil Eye"));
        // EFST_SP_SHA (1064) has no English client title and no presentation
        // row at all; the buff bar uses the generic fallback name.
        assert!(lookup(1064).is_none() || lookup(1064).unwrap().name.is_none());
    }

    #[test]
    fn legacy_icons_are_covered() {
        let legacy = legacy_tables();
        assert_eq!(legacy.icons.len(), 355);
        for (status_id, icon) in &legacy.icons {
            let info = lookup(*status_id).unwrap_or_else(|| panic!("status {status_id} is missing"));
            // The texture loader resolves GRF names case-insensitively; the old
            // table and the client tables disagree on ASCII case for some icons.
            let actual = info.icon.unwrap_or_default();
            assert!(
                actual.eq_ignore_ascii_case(icon),
                "status {status_id} icon changed: {actual:?} != {icon:?}"
            );
        }
    }

    #[test]
    fn extra_names_are_covered() {
        let legacy = legacy_tables();
        assert_eq!(legacy.extra_names.len(), 10);
        for (status_id, name) in &legacy.extra_names {
            let info = lookup(*status_id).unwrap_or_else(|| panic!("status {status_id} is missing"));
            assert_eq!(info.name, Some(name.as_str()), "status {status_id} extra name changed");
        }
    }

    #[test]
    fn known_statuses_are_named_and_have_icons() {
        // The statuses the buff bar/tooltip tests used before the data file.
        for (status_id, name) in [
            (0_u16, "Provoke"),
            (1, "Endure"),
            (2, "Two-Hand Quicken"),
            (3, "Improve Concentration"),
            (9, "Angelus"),
            (10, "Blessing"),
            (12, "Increase Agility"),
            (27, "Riding"),
            (110, "Assumptio"),
            (473, "Assumptio"),
            (875, "Stone Curse"),
            (883, "Poison"),
            (890, "Deadly Poison"),
            (241, "STR Food"),
        ] {
            let info = lookup(status_id).unwrap_or_else(|| panic!("status {status_id} is missing"));
            assert_eq!(info.name, Some(name), "status {status_id} name changed");
            assert!(info.icon.is_some(), "status {status_id} lost its icon");
        }
        // Bleeding has a curated English name but no official status icon.
        let bleeding = lookup(889).unwrap();
        assert_eq!(bleeding.name, Some("Bleeding"));
        assert_eq!(bleeding.category, StatusEffectCategory::Debuff);

        // The icon path is relative to `data\texture`.
        assert_eq!(
            lookup(2).unwrap().icon.map(|icon| format!("effect\\{icon}")),
            Some("effect\\투핸드퀴큰.tga".to_owned())
        );
        assert_eq!(
            lookup(110).unwrap().icon.map(|icon| format!("effect\\{icon}")),
            Some("effect\\icon05.tga".to_owned())
        );
    }

    #[test]
    fn categories_come_from_the_client_data() {
        assert_eq!(lookup(10).unwrap().category, StatusEffectCategory::Buff);
        // The client title colour is the presentation category: Provoke is a
        // green (buff) title in `stateiconinfo.lub`, Decrease AGI is a red
        // (debuff) one.
        assert_eq!(lookup(0).unwrap().category, StatusEffectCategory::Buff);
        assert_eq!(lookup(13).unwrap().category, StatusEffectCategory::Debuff);
        // Riding is the client's `COLOR_TITLE_TOGGLE` example.
        assert_eq!(lookup(27).unwrap().category, StatusEffectCategory::Toggle);
        // Every category value is reachable from the data file.
        let table = super::table();
        for category in [
            StatusEffectCategory::Buff,
            StatusEffectCategory::Debuff,
            StatusEffectCategory::Toggle,
            StatusEffectCategory::System,
        ] {
            assert!(
                table.statuses.iter().any(|status| status.category == category),
                "category {category:?} is not present in the data"
            );
        }
    }

    #[test]
    fn refresh_and_stack_policies_are_data_driven() {
        let table = super::table();
        assert!(table.statuses.iter().all(|status| status.refresh == StatusRefreshPolicy::Replace));
        assert!(table.statuses.iter().all(|status| status.stack == StatusStackPolicy::Single));
    }

    #[test]
    fn assumptio_and_the_documented_buff_auras_are_looked_up() {
        for status_id in [110_u16, 473] {
            let aura = status_aura_spec(status_id).unwrap_or_else(|| panic!("status {status_id} lost its Assumptio aura"));
            assert_eq!(aura.kind, StatusAuraKind::PersistentGlow);
            assert_eq!(aura.ground_texture, "effect\\whitelight.tga");
        }
        // Party/cash Assumptio uses an identical spec row.
        assert_eq!(status_aura_spec(110), status_aura_spec(473));

        // Only Assumptio keeps a persistent glow; the other buffs must not.
        for status_id in [10_u16, 12, 9, 3] {
            assert!(status_aura_spec(status_id).is_none(), "status {status_id} must not glow");
        }

        assert!(status_aura_spec(30_000).is_none());
        assert!(status_aura_spec(875).is_none(), "Stone Curse must not glow");
    }

    #[test]
    fn value_labels_follow_the_data_file() {
        assert_eq!(value_lines(64, [3, 0, 0]), vec!["Element: Fire".to_owned()]);
        assert_eq!(value_lines(64, [99, 0, 0]), vec!["Element: Unknown".to_owned()]);
        assert_eq!(value_lines(250, [50, 0, 0]), vec!["Base EXP boost: 50%".to_owned()]);
        assert_eq!(value_lines(252, [10, 0, 0]), vec!["Item drop boost: 10%".to_owned()]);
        assert_eq!(value_lines(312, [25, 0, 0]), vec!["Job EXP boost: 25%".to_owned()]);
        assert_eq!(value_lines(673, [1, 0, 0]), vec!["Push cart: 1".to_owned()]);
        assert_eq!(value_lines(621, [1002, 0, 0]), vec!["Monster transform: #1002".to_owned()]);

        // Unknown statuses keep the raw values; statuses without labels too.
        assert_eq!(value_lines(1234, [5, 0, 7]), vec!["Value: 5 / 7".to_owned()]);
        assert_eq!(value_lines(875, [0, 4, 0]), vec!["Value: 4".to_owned()]);
        assert!(value_lines(64, [0, 0, 0]).is_empty());
    }

    #[test]
    fn value_label_metadata_is_consistent() {
        let table = super::table();
        for status in &table.statuses {
            let mut slots = Vec::new();
            for label in status.value_labels {
                assert!((1..=3).contains(&label.slot));
                assert!(!label.label.is_empty());
                assert!(!slots.contains(&label.slot), "status {} has duplicate value slots", status.id);
                slots.push(label.slot);
            }
            if status.id == 64 {
                assert_eq!(status.value_labels.len(), 1);
                assert_eq!(status.value_labels[0].format, StatusValueFormat::Element);
                assert_eq!(status.value_labels[0].label, "Element");
            }
            if status.id == 621 {
                assert_eq!(status.value_labels[0].format, StatusValueFormat::Id);
            }
        }
    }

    #[test]
    fn malformed_data_is_rejected() {
        assert!(validate("(").is_err());
        assert!(validate("").is_err());

        // Unknown field (`deny_unknown_fields` makes data typos loud).
        let unknown_field = FALLBACK.replacen(
            "            category: Buff,\n            refresh: Replace,",
            "            category: Buff,\n            typo: 1,\n            refresh: Replace,",
            1,
        );
        assert!(validate(&unknown_field).is_err(), "an unknown field must be rejected");

        // Duplicate status id.
        let duplicate = FALLBACK.replacen("            id: 1,\n", "            id: 0,\n", 1);
        assert!(validate(&duplicate).is_err(), "a duplicate status id must be rejected");

        // Missing mandatory field.
        let missing = FALLBACK.replacen("            category: Buff,\n", "", 1);
        assert!(validate(&missing).is_err(), "a missing category must be rejected");

        // Wrong icon extension.
        let bad_icon = FALLBACK.replacen("            icon: \"프로보크.tga\",", "            icon: \"프로보크.bmp\",", 1);
        assert!(validate(&bad_icon).is_err(), "a non-.tga status icon must be rejected");
    }

    #[test]
    fn unknown_statuses_have_no_data() {
        assert!(lookup(30_000).is_none());
        assert!(status_aura_spec(30_000).is_none());
        assert!(value_lines(30_000, [0, 0, 0]).is_empty());
        assert_eq!(value_lines(30_000, [1, 0, 0]), vec!["Value: 1".to_owned()]);
    }
}
